use thinkthen::{Answer, Engine, Question};
let tt = Engine::from_env()?;

// build a question once. The band's middle is Unsure
let refund = Question::decide(
    "Does the customer ask for a refund?")?.band(0.2, 0.8)?;
match tt.decide(&refund, "I want to send this back.")? {
    Answer::Unsure => println!("a person reads it"),
    other => println!("{other:?}"),
}
